package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	var s string
	fmt.Fscan(reader, &s)

	arr := []byte(s)
	removed := 0

	for c := byte('z'); c >= 'b'; c-- {
		for {
			found := -1
			for i := 0; i < len(arr); i++ {
				if arr[i] == c {
					if (i > 0 && arr[i-1] == c-1) || (i < len(arr)-1 && arr[i+1] == c-1) {
						found = i
						break
					}
				}
			}
			if found == -1 {
				break
			}
			arr = append(arr[:found], arr[found+1:]...)
			removed++
		}
	}

	fmt.Println(removed)
}
